-- ALL PROMINENT GHANA database
create extension if not exists pgcrypto;
create table if not exists public.currencies(code text primary key,name text not null,symbol text not null);
insert into public.currencies(code,name,symbol) values ('GHS','Ghana Cedi','GH₵'),('USD','US Dollar','$'),('EUR','Euro','€'),('GBP','British Pound','£'),('CNY','Chinese Yuan','¥') on conflict do nothing;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,location text,avatar_url text,verified boolean default false,created_at timestamptz default now());
create table if not exists public.categories(id bigint generated always as identity primary key,name text unique not null);
create table if not exists public.listings(id bigint generated always as identity primary key,seller_id uuid references auth.users(id) on delete cascade,category_id bigint references public.categories(id),title text not null,description text,price numeric(14,2) not null,currency_code text references public.currencies(code) default 'GHS',location text,status text default 'active',featured boolean default false,created_at timestamptz default now());
create table if not exists public.listing_images(id bigint generated always as identity primary key,listing_id bigint references public.listings(id) on delete cascade,image_url text not null);
create table if not exists public.listing_videos(id bigint generated always as identity primary key,listing_id bigint references public.listings(id) on delete cascade,video_url text not null,thumbnail_url text,created_at timestamptz default now());
create table if not exists public.stores(id bigint generated always as identity primary key,owner_id uuid references auth.users(id) on delete cascade,name text not null,description text,logo_url text,verified boolean default false,created_at timestamptz default now());
create table if not exists public.messages(id bigint generated always as identity primary key,sender_id uuid references auth.users(id) on delete cascade,receiver_id uuid references auth.users(id) on delete cascade,listing_id bigint references public.listings(id) on delete cascade,message text not null,created_at timestamptz default now());
create table if not exists public.favorites(user_id uuid references auth.users(id) on delete cascade,listing_id bigint references public.listings(id) on delete cascade,created_at timestamptz default now(),primary key(user_id,listing_id));
create table if not exists public.reviews(id bigint generated always as identity primary key,reviewer_id uuid references auth.users(id) on delete cascade,seller_id uuid references auth.users(id) on delete cascade,rating int check(rating between 1 and 5),comment text,created_at timestamptz default now());
create table if not exists public.video_ads(id bigint generated always as identity primary key,advertiser_id uuid references auth.users(id) on delete cascade,title text not null,description text,video_url text not null,thumbnail_url text,currency_code text references public.currencies(code) default 'GHS',budget numeric(14,2),start_date timestamptz,end_date timestamptz,status text default 'pending',views bigint default 0,clicks bigint default 0,watch_seconds bigint default 0,created_at timestamptz default now());
create table if not exists public.ad_events(id bigint generated always as identity primary key,ad_id bigint references public.video_ads(id) on delete cascade,event_type text not null,viewer_id uuid references auth.users(id) on delete set null,created_at timestamptz default now());
insert into public.categories(name) values ('Phones & Tablets'),('Cars'),('Property'),('Fashion'),('Electronics'),('Jobs & Services'),('Home & Garden'),('Agriculture') on conflict do nothing;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.listings enable row level security; alter table public.listing_images enable row level security; alter table public.listing_videos enable row level security; alter table public.stores enable row level security; alter table public.messages enable row level security; alter table public.favorites enable row level security; alter table public.reviews enable row level security; alter table public.video_ads enable row level security; alter table public.ad_events enable row level security;
create policy "categories public read" on public.categories for select using(true); create policy "currencies public read" on public.currencies for select using(true);
create policy "listings public read" on public.listings for select using(status='active'); create policy "users create listings" on public.listings for insert to authenticated with check(auth.uid()=seller_id); create policy "users update own listings" on public.listings for update to authenticated using(auth.uid()=seller_id); create policy "users delete own listings" on public.listings for delete to authenticated using(auth.uid()=seller_id);
create policy "profiles own" on public.profiles for all to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "images public read" on public.listing_images for select using(true); create policy "videos public read" on public.listing_videos for select using(true);
create policy "store public read" on public.stores for select using(true); create policy "store owner write" on public.stores for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id);
create policy "message participants read" on public.messages for select to authenticated using(auth.uid()=sender_id or auth.uid()=receiver_id); create policy "message sender insert" on public.messages for insert to authenticated with check(auth.uid()=sender_id);
create policy "favorites own" on public.favorites for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "reviews public read" on public.reviews for select using(true); create policy "reviewer insert" on public.reviews for insert to authenticated with check(auth.uid()=reviewer_id);
create policy "active ads public read" on public.video_ads for select using(status='active'); create policy "advertiser manage own ads" on public.video_ads for all to authenticated using(auth.uid()=advertiser_id) with check(auth.uid()=advertiser_id);
create policy "ad events insert" on public.ad_events for insert with check(auth.uid()=viewer_id or viewer_id is null); create policy "ad events advertiser read" on public.ad_events for select to authenticated using(exists(select 1 from public.video_ads a where a.id=ad_id and a.advertiser_id=auth.uid()));
